public async Task<PagedResult<OrderSummaryDto>> ListOrdersAsync(
    string tenantId, int page, int size, CancellationToken ct)
{
    var query = _db.Orders.AsNoTracking()
        .Where(o => o.TenantId == tenantId)
        .OrderByDescending(o => o.CreatedAt)
        .Select(o => new OrderSummaryDto(o.Id, o.Total, o.Status));

    var total = await query.CountAsync(ct);
    var items = await query.Skip((page - 1) * size).Take(size).ToListAsync(ct);
    return new PagedResult<OrderSummaryDto>(items, total, page, size);
}

private static readonly Func<AppDbContext, int, Task<Order?>> GetOrderById =
    EF.CompileAsyncQuery((AppDbContext db, int id) =>
        db.Orders.AsNoTracking().FirstOrDefault(o => o.Id == id));

public Task<Order?> GetOrderAsync(int id, CancellationToken ct) =>
    GetOrderById(_db, id);

